  if (st.state && !["held", "creating", "invited", "open", "pending"].includes(st.state) && st.state !== "held") { console.log("FINAL", JSON.stringify(st).slice(0, 2500)); break; }
  if (st.state === "locked" || st.state === "cancelled" || st.state === "refunded") { console.log("FINAL", JSON.stringify(st).slice(0, 2500)); break; }
  const n = await call("wait_for_news", { after, seconds: 40 });
  for (const item of n.news || []) console.log("NEWS:", JSON.stringify(item).slice(0, 500));
  if (typeof n.last === "number") after = n.last;
}
